CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "displayName" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE "Document" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "User"("id"), "title" TEXT NOT NULL, "plainText" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE "DocumentRevision" ("id" TEXT PRIMARY KEY, "documentId" TEXT NOT NULL REFERENCES "Document"("id"), "revision" INTEGER NOT NULL, "operation" JSONB NOT NULL, "snapshot" TEXT NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT now(), UNIQUE("documentId", "revision"));
CREATE TABLE "Suggestion" ("id" TEXT PRIMARY KEY, "documentId" TEXT REFERENCES "Document"("id"), "type" TEXT NOT NULL, "severity" TEXT NOT NULL, "originalText" TEXT NOT NULL, "suggestedText" TEXT NOT NULL, "explanation" TEXT NOT NULL, "startIndex" INTEGER NOT NULL, "endIndex" INTEGER NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "sourceProvider" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'open', "createdAt" TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE "UserPreference" ("userId" TEXT PRIMARY KEY REFERENCES "User"("id"), "locale" TEXT NOT NULL DEFAULT 'en-US', "formality" TEXT NOT NULL DEFAULT 'neutral', "enabledSuggestionTypes" TEXT[] NOT NULL, "allowProductImprovement" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "ProductEvent" ("id" TEXT PRIMARY KEY, "userId" TEXT, "tenantId" TEXT, "type" TEXT NOT NULL, "documentId" TEXT, "suggestionId" TEXT, "metadata" JSONB NOT NULL, "occurredAt" TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE "TeamSetting" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "key" TEXT NOT NULL, "value" JSONB NOT NULL, "updatedAt" TIMESTAMP NOT NULL DEFAULT now(), UNIQUE("tenantId", "key"));
